import { DRAW_TIMEZONE } from 'src/config-global';

type TimeParts = {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
};

const DRAW_TIME_FORMATTER = new Intl.DateTimeFormat('en-US', {
  timeZone: DRAW_TIMEZONE,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
});

const getTimeParts = (date = new Date()): TimeParts => {
  const parts = DRAW_TIME_FORMATTER.formatToParts(date);
  const get = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((part) => part.type === type)?.value ?? 0);

  return {
    year: get('year'),
    month: get('month'),
    day: get('day'),
    hour: get('hour'),
    minute: get('minute'),
    second: get('second'),
  };
};

const parseCloseTime = (endTime?: string) => {
  if (!endTime) return null;
  const [hRaw, mRaw] = endTime.slice(0, 5).split(':');
  const hours = Number(hRaw);
  const minutes = Number(mRaw);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  return { hours, minutes };
};

export const getSecondsUntilDrawClose = (endTime?: string, now = new Date()) => {
  const closeTime = parseCloseTime(endTime);
  if (!closeTime) return null;

  const tzNow = getTimeParts(now);
  const nowSeconds = tzNow.hour * 3600 + tzNow.minute * 60 + tzNow.second;
  const closeSeconds = closeTime.hours * 3600 + closeTime.minutes * 60;
  return closeSeconds - nowSeconds;
};

export const isDrawClosed = (endTime?: string, now = new Date()) => {
  const secondsUntilClose = getSecondsUntilDrawClose(endTime, now);
  if (secondsUntilClose === null) return false;
  return secondsUntilClose <= 0;
};

export const formatDrawCartDate = (tirageCloseTime?: string, now = new Date()) => {
  const tzNow = getTimeParts(now);
  const closeTime = parseCloseTime(tirageCloseTime);
  const closeHour = closeTime?.hours ?? tzNow.hour;
  const closeMinute = closeTime?.minutes ?? tzNow.minute;
  const pad = (value: number) => String(value).padStart(2, '0');

  return `${pad(tzNow.day)}/${pad(tzNow.month)}/${tzNow.year} - ${pad(closeHour)}:${pad(
    closeMinute
  )}`;
};
